"""Independent analytic expectations, not generated by the candidate detector."""
import numpy as np
from cbdk_geometry import Mesh
from cbdk_geometry.fixtures import pair


def analytic_cases():
    base=[]
    for kind, hit in [('cross',True),('coplanar',True),('touch',True),
                     ('separate',False),('coplanar_separate',False),('near_miss',False)]:
        base.append((kind,pair(kind),hit))
    for gap in (1e-12,1e-10):
        m=pair('separate');v=m.vertices.copy();v[3:,2]=gap
        base.append((f'positive_gap_{gap}',Mesh(v,m.faces),False))
    for depth in (1e-9,1e-10):
        # Both faces lie above the shared x-axis: positive-area overlap.
        base.append((f'shared_edge_sliver_{depth}',Mesh(
            [[0,0,0],[1,0,0],[0,1,0],[.5,depth,0]],[[0,1,2],[1,0,3]]),True))
        # Intersection segment from (0,0,0) to (depth,depth,0).
        base.append((f'shared_vertex_sliver_{depth}',Mesh(
            [[0,0,0],[1,0,0],[0,1,0],[depth,depth,-1],[depth,depth,1]],
            [[0,1,2],[0,3,4]]),True))
    base.append(('shared_edge_only',Mesh([[0,0,0],[1,0,0],[0,1,0],[0,-1,0]],[[0,1,2],[1,0,3]]),False))
    base.append(('shared_vertex_only',Mesh([[0,0,0],[1,0,0],[0,1,0],[0,0,1],[-1,0,1]],[[0,1,2],[0,3,4]]),False))
    base.append(('duplicate',Mesh([[0,0,0],[1,0,0],[0,1,0]],[[0,1,2],[2,1,0]]),True))
    for name,m,hit in base:
        for scale in (1e-6,1.,1e6):
            for reverse in (False,True):
                yield dict(name=name,scale=scale,reverse=reverse,expected=hit,
                           mesh=Mesh(m.vertices*scale,m.faces[:,::-1] if reverse else m.faces))
